"""Extend current focused browser coverage; preserve every preceding assertion except current aggregate counts."""
from setup_deseq2_reference import ROOT

EXTRA=r'''
 await page.setViewportSize({width:1440,height:1000});await page.goto('http://127.0.0.1:8768/literature-review.html');await page.evaluate(()=>document.documentElement.dataset.theme='light');await page.locator('#tools-tab').click();await page.locator('#query').fill('Rsubread');const rc=page.locator('#results article').filter({has:page.getByRole('heading',{name:/^Rsubread \(/i})});assert.equal(await rc.count(),1);const rt=(await rc.innerText()).toLowerCase();for(const term of ['RsubreadWorkflowCli','2.26.0','2.23.2','4.6.1','4.4.1','Windows','58','14-field','upstream','double-GeneID','checkFragLength','countReadPairs','whole'])assert(rt.includes(term.toLowerCase()),term);await rc.screenshot({path:path.join(out,'rsubread-card-desktop.png'),style:'header{visibility:hidden!important}'});checks.push('Rsubread card shows exact original editions, full count-list/native checks, tested compiler variants and source/runtime/input boundaries');
 const rr=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/omics-2023-2026/tool-inventory.json'))).find(t=>t.id==='rsubread');const rp=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/rsubread-execution-development/VALIDATION.json')));assert.equal(rr.implementation_status,'upstream-adapter-validated');assert.equal(rr.source_roles_reviewed,6);assert.equal(rr.development_candidate,rp.artifact.path);assert.equal(rr.development_candidate_sha256,rp.artifact.sha256);assert.equal(rr.development_cli_class,'org.jlinalg.cli.RsubreadWorkflowCli');assert.equal(rr.runtime_binding_cli_class,'org.jlinalg.cli.RsubreadRuntimeCli');assert(rr.runtime_export_command.includes('export_rsubread_runtime_package.py'));for(const flag of ['analysis_installs_software','canonical_adapter_available','independent_read_counting','independent_junction_counting','whole_package_implemented','whole_paper_reproduced'])assert.equal(rr[flag],false);checks.push('Rsubread row binds the exact shipped original-counting artifact and separate permission-controlled export/runtime entry points');
 const rd=JSON.parse(fs.readFileSync(path.join(root,'tools/literature/rsubread-use-reviews.json'))).reviews;assert.equal(rd.length,6);await page.locator('#papers-tab').click();for(const d of rd){const paper=papers.find(p=>p.paper_id===d.paper_id);await page.locator('#query').fill(paper.doi);assert.equal(await page.locator('#results article').count(),1);const content=clean(await page.locator('#'+d.paper_id).textContent());assert(content.includes(clean(d.review.use_summary)),d.paper_id+' summary');assert(content.includes(clean(d.review.implementation_scope_note)),d.paper_id+' source scope');}checks.push('all six Rsubread roles preserve literal versions, linked-code omissions, generic loading, exon aggregation uncertainty and separate downstream methods');
 await page.goto('http://127.0.0.1:8768/literature-warnings.html');const ra=page.locator('#rsubread-required-actions');assert(await ra.isVisible());const rat=(await ra.innerText()).toLowerCase();for(const term of ['SKIP3','FAIL2','analysis_admitted=true','PROVISIONAL','NEW paths','Analysis installs nothing','--allow-install','Linux','checkFragLength','requireBothEndsMapped','countReadPairs','P133','P139','P172','P223','22','coerce','Double-storage','structural','Cell Ranger'])assert(rat.includes(term.toLowerCase()),term);await ra.screenshot({path:path.join(out,'rsubread-actions-desktop.png'),style:'header{visibility:hidden!important}'});checks.push('Rsubread warnings prominently explain exact permitted setup, dependent-analysis skips, atomic failure, counting-unit/fragment omissions and source coercion limits');
 await page.setViewportSize({width:390,height:1000});await page.evaluate(()=>document.documentElement.dataset.theme='dark');assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await ra.screenshot({path:path.join(out,'rsubread-actions-mobile-dark.png'),style:'header{visibility:hidden!important}'});assert.equal(errors.length,0,errors.join('\n'));const rroles=JSON.parse(fs.readFileSync(path.join(root,'docs/literature/omics-2023-2026/rsubread-role-coverage.json')));assert.equal(rroles.prior_reviews,1000);assert.equal(rroles.unchanged_prior_reviews,997);assert.equal(rroles.refined_existing_reviews,3);assert.equal(rroles.new_reviews,3);assert.equal(rroles.total_reviews,1003);assert.equal(rroles.supporting_pointers,349);checks.push('Rsubread dark warnings fit390px without overflow or browser errors; exact three-new/three-refined extension preserves all997 unrelated reviews');
'''


def generated():
    tools=ROOT/'tools/literature';text=(tools/'check_hifiasm_catalog_review_ui.cjs').read_text(encoding='utf8')
    changes=[("['upstream-adapter-validated',72],['missing',252]","['upstream-adapter-validated',73],['missing',251]"),('400 cataloged tools,89 new integrations,252 missing','400 cataloged tools,90 new integrations,251 missing'),('assert.equal(gu.length,1000)','assert.equal(gu.length,1003)'),('length,0),347)','length,0),349)'),('1000 roles and347 support pointers','1003 roles and349 support pointers'),('hifiasm-ui-verification.json','rsubread-ui-verification.json'),('Passed31 focused current CellPhoneDB, Palantir, scFates, GSEApy and hifiasm browser checks','Passed36 focused current CellPhoneDB, Palantir, scFates, GSEApy, hifiasm and Rsubread browser checks')]
    for old,new in changes:assert text.count(old)==1,old;text=text.replace(old,new)
    marker=' const inventory=JSON.parse';assert text.count(marker)==1;text=text.replace(marker,EXTRA+marker)
    wrapper=(tools/'validate_hifiasm_catalog_ui.py').read_text(encoding='utf8').replace('hifiasm','rsubread')
    return {tools/'check_rsubread_catalog_review_ui.cjs':text.encode(),tools/'validate_rsubread_catalog_ui.py':wrapper.encode()}


def verify():
    for path,raw in generated().items():assert path.read_bytes()==raw,'Focused browser-source derivation differs: '+str(path)


if __name__=='__main__':
    for path,raw in generated().items():
        if path.exists():assert path.read_bytes()==raw
        else:path.write_bytes(raw)
    verify();print('Prepared299 unchanged general plus36 current focused browser checks')
